const VerifiedOpcodeEntry* GetVerifiedOpcodeTable(size_t* out_count) noexcept {
    if (out_count) {
        *out_count = 4993u;
    }
    return kVerifiedOpcodes;
}

uint32_t LookupVerifiedOpcode(uint32_t vaddr) noexcept {
    for (size_t i = 0u; i < 4993u; ++i) {
        if (kVerifiedOpcodes[i].vaddr == vaddr) {
            return kVerifiedOpcodes[i].opcode_u32;
        }
    }
    return 0u;
}

const ExportedSymbolEntry* GetExportedSymbolTable(size_t* out_count) noexcept {
    if (out_count) {
        *out_count = 434u;
    }
    return kExportedSymbols;
}

bool RunSelfVerificationSuite() noexcept {
    // 1. Verify HarfBuzz dynamic loader table size (0x138 = 312 bytes, 39 symbols)
    if (sizeof(HarfbuzzFuncTable) != 0x138u || !HarfbuzzLib::HasHarfbuzzLib()) {
        return false;
    }
    // 2. Verify DefaultBidiResult vectorized + scalar initialization
    uint8_t levels[12] = {0};
    uint32_t vmap[12] = {0};
    uint32_t lmap[12] = {0};
    DefaultBidiResult(12u, levels, vmap, lmap);
    for (uint32_t i = 0u; i < 12u; ++i) {
        if (levels[i] != 0xFEu || vmap[i] != i || lmap[i] != i) {
            return false;
        }
    }
    // 3. Verify UTF-8 / UTF-32 round-trip and U8CharToU32
    uint32_t byte_len = 0u;
    const int32_t cp = base::U8CharToU32("\xE2\x80\xA8", &byte_len);
    if (cp != 0x2028 || byte_len != 3u) {
        return false;
    }
    // 4. Verify BoundaryAnalyst codepoint classification
    if (BoundaryAnalyst::ClassifyCodepointForBreak(0x4E2Du) != 2u ||
        BoundaryAnalyst::ClassifyCodepointForBreak(0x0020u) != 1u ||
        BoundaryAnalyst::ClassifyCodepointForBreak(0x002Du) != 4u ||
        BoundaryAnalyst::ClassifyCodepointForBreak(0x3002u) != 5u) {
        return false;
    }
    // 5. Verify LayoutMeasurer::CalcElementY centering (-0.5f at 0x02cbe0)
    const float y_center = LayoutMeasurer::CalcElementY(
        CharacterVerticalAlignment::kCenter, 10.0f, 4.0f, 6.0f, 2.0f);
    if (std::fabs(y_center - (-3.0f)) > kFloatEpsilon) {
        return false;
    }
    return true;
}

